/// Helper function to retrieve the diagnosis health status object for a given screen ID or route path.
ScreenHealthStatus getScreenHealth(String screenIdOrRoutePath) {
  final cleanPath = screenIdOrRoutePath.trim();
  
  // Search by route path first
  if (screenHealthRegistry.containsKey(cleanPath)) {
    return screenHealthRegistry[cleanPath]!;
  }
  
  // Search by screen ID or name
  for (final status in screenHealthRegistry.values) {
    if (status.screenName == cleanPath || status.routePath == cleanPath || status.componentFile.contains(cleanPath)) {
      return status;
    }
  }
  
  // Fallback default empty diagnostic object
  return ScreenHealthStatus(
    screenName: cleanPath,
    routePath: cleanPath,
    componentFile: 'Unknown',
    currentStage: 0,
    progressPercent: 0,
    isPlaceholder: true,
    hasRealUi: false,
    hasButtons: false,
    hasForms: false,
    hasTables: false,
    hasApiCalls: false,
    hasDbConnection: false,
    hasValidation: false,
    hasErrorHandling: false,
    hasLoadingState: false,
    hasEmptyState: false,
    isProductionReady: false,
    missingItems: const ['File not found or registered'],
    nextAction: 'Ensure route is properly registered in screen_registry.dart',
    lastCheckedAt: DateTime.now().toIso8601String(),
  );
}

/// Helper function to ask a screen a question and receive a human-language response.
String askScreen(String routePath, String question) {
  final health = getScreenHealth(routePath);
  final q = question.toLowerCase();
  
  if (q.contains('are you ok') || q.contains('is ok') || q.contains('status')) {
    if (health.isProductionReady) {
      return "Screen: ${health.screenName}\nStatus: OK\nProgress: 100%\nDescription: I am fully operational, verified by QA, and ready for production.";
    }
    
    final problem = health.isPlaceholder 
        ? "I contain placeholder or stub elements capped at Stage 2."
        : "I am at Stage ${health.currentStage} with ${health.progressPercent}% progress.";
        
    return "Screen: ${health.screenName}\nStatus: Not OK\nProgress: ${health.progressPercent}%\nProblem: ${problem}\nNext action: ${health.nextAction}";
  }
  
  if (q.contains('what is missing') || q.contains('missing') || q.contains('need')) {
    if (health.missingItems.isEmpty) {
      return "I have no missing items. I am fully operational and completed.";
    }
    final listStr = health.missingItems.map((item) => "- $item").join('\n');
    return "Screen: ${health.screenName}\nI need the following elements completed:\n$listStr\nNext action: ${health.nextAction}";
  }
  
  if (q.contains('ready') || q.contains('production')) {
    if (health.isProductionReady) {
      return "Yes! I am 100% production ready and verified by automated QA specifications.";
    }
    return "No, I am not production ready. My current progress is ${health.progressPercent}% and I still need: ${health.missingItems.join(', ')}.";
  }
  
  if (q.contains('api') || q.contains('network')) {
    if (health.hasApiCalls) {
      return "Yes, my API communication layer is fully connected and error-handled.";
    }
    return "No, my API connection is missing. I need the networking client wired up.";
  }
  
  if (q.contains('db') || q.contains('database') || q.contains('save') || q.contains('read')) {
    if (health.hasDbConnection) {
      return "Yes, my local persistence save and read flows are working correctly.";
    }
    return "No, my local database read/write transaction flows are missing.";
  }
  
  if (q.contains('mock') || q.contains('sample') || q.contains('simulated')) {
    if (health.isPlaceholder) {
      return "Yes, I am relying on mock stubs or placeholder text.";
    }
    if (health.hasApiCalls && health.hasDbConnection) {
      return "No, I am fully connected to live APIs and DB services.";
    }
    return "I am partially using simulated data models as fallbacks because some live integrations are not completed.";
  }
  
  return "Screen: ${health.screenName}\nProgress: ${health.progressPercent}%\nNext action: ${health.nextAction}";
}

// Dynamic database loading and updating functions using sqlite3 package

List<ScreenHealthStatus> loadAllScreensFromDb() {
  final dbPath = r"C:\Users\Admin2\Documents\GitHub\primecare-platform\.agents\governance\governance.db";
  if (!File(dbPath).existsSync()) {
    return screenHealthRegistry.values.toList();
  }
  
  try {
    final db = sqlite3.open(dbPath);
    final results = db.select('SELECT * FROM screens');
    final List<ScreenHealthStatus> list = [];
    for (final row in results) {
      final routePath = (row['route_path'] ?? '') as String;
      if (routePath.isEmpty) continue;
      
      final progress = (row['progress_percent'] ?? 0) as int;
      final isPlaceholder = (row['blocker'] != null && (row['blocker'] as String).contains('Placeholder'));
      
      // Compute missing items
      final currentStage = _mapProgressToStage(progress);
      final missingItems = <String>[];
      if (currentStage < 2) missingItems.add("HTML structure definition");
      if (currentStage < 3) missingItems.add("Real visual elements (cards/buttons)");
      if (currentStage < 4) missingItems.add("Modular state components wired");
      if (currentStage < 5) missingItems.add("State controller business logic");
      if (currentStage < 6) missingItems.add("API endpoint connection client");
      if (currentStage < 7) missingItems.add("Local DB save/read transaction flows");
      if (currentStage < 8) missingItems.add("Input field form validation");
      if (currentStage < 9) missingItems.add("User interaction callbacks wired");
      if (currentStage < 10) missingItems.add("QA verification spec coverage");
      if (currentStage < 11) missingItems.add("Production release certification");

      list.add(ScreenHealthStatus(
        screenName: (row['screen_name'] ?? '') as String,
        routePath: routePath,
        componentFile: (row['actual_file_path'] ?? (row['file_path'] ?? '')) as String,
        currentStage: currentStage,
        progressPercent: progress,
        isPlaceholder: isPlaceholder,
        hasRealUi: currentStage >= 3,
        hasButtons: currentStage >= 3,
        hasForms: currentStage >= 3,
        hasTables: currentStage >= 3,
        hasApiCalls: currentStage >= 6,
        hasDbConnection: currentStage >= 7,
        hasValidation: currentStage >= 8,
        hasErrorHandling: currentStage >= 6,
        hasLoadingState: currentStage >= 5,
        hasEmptyState: currentStage >= 4,
        isProductionReady: currentStage >= 11,
        missingItems: missingItems,
        nextAction: (row['next_action'] ?? '') as String,
        lastCheckedAt: (row['last_verified_at'] ?? DateTime.now().toIso8601String()) as String,
        diagnosisEnabled: ((row['diagnosis_enabled'] ?? 0) as int) == 1,
        diagnosisReplyStatus: (row['diagnosis_reply_status'] ?? 'NOT_TESTED') as String,
        diagnosisLastQuestion: row['diagnosis_last_question'] as String?,
        diagnosisLastAnswer: row['diagnosis_last_answer'] as String?,
        diagnosisLastCheckedAt: row['diagnosis_last_checked_at'] as String?,
        diagnosisError: row['diagnosis_error'] as String?,
        buttonCount: (row['button_count'] ?? 0) as int,
        formFieldCount: (row['form_field_count'] ?? 0) as int,
        linkCount: (row['link_count'] ?? 0) as int,
        tableActionCount: (row['table_action_count'] ?? 0) as int,
        filterCount: (row['filter_count'] ?? 0) as int,
        navigationActionCount: (row['navigation_action_count'] ?? 0) as int,
        totalInteractiveObjects: (row['total_interactive_objects'] ?? 0) as int,
        screenPurpose: row['screen_purpose'] as String?,
        primaryUserGoal: row['primary_user_goal'] as String?,
        expectedUserActions: row['expected_user_actions'] as String?,
        businessReason: row['business_reason'] as String?,
        screenPurposeStatus: (row['screen_purpose_status'] ?? 'NO_USER_VALUE') as String,
        needsReview: ((row['needs_review'] ?? 0) as int) == 1,
        productionReady: ((row['production_ready'] ?? 0) as int) == 1,
        falseProgress: ((row['false_progress'] ?? 0) as int) == 1,
        roleKey: row['role_key'] as String?,
        roleName: row['role_name'] as String?,
        roleCategory: row['role_category'] as String?,
        roleScreenOrder: (row['role_screen_order'] ?? 0) as int,
        roleCompletionPercent: (row['role_completion_percent'] ?? 0) as int,
        roleDocPath: row['role_doc_path'] as String?,
        visualStatus: row['visual_status'] as String?,
      ));
    }
    db.dispose();
    return list;
  } catch (e) {
    return screenHealthRegistry.values.toList();
  }
}

int _mapProgressToStage(int progress) {
  if (progress >= 100) return 11;
  if (progress >= 95) return 10;
  if (progress >= 90) return 9;
  if (progress >= 80) return 8;
  if (progress >= 70) return 7;
  if (progress >= 60) return 6;
  if (progress >= 50) return 5;
  if (progress >= 40) return 4;
  if (progress >= 30) return 3;
  if (progress >= 20) return 2;
  if (progress >= 10) return 1;
  return 0;
}

void setDiagnosisEnabled(String routePath, bool enabled) {
  if (screenHealthRegistry.containsKey(routePath)) {
    final old = screenHealthRegistry[routePath]!;
    screenHealthRegistry[routePath] = ScreenHealthStatus(
      screenName: old.screenName,
      routePath: old.routePath,
      componentFile: old.componentFile,
      currentStage: old.currentStage,
      progressPercent: old.progressPercent,
      isPlaceholder: old.isPlaceholder,
      hasRealUi: old.hasRealUi,
      hasButtons: old.hasButtons,
      hasForms: old.hasForms,
      hasTables: old.hasTables,
      hasApiCalls: old.hasApiCalls,
      hasDbConnection: old.hasDbConnection,
      hasValidation: old.hasValidation,
      hasErrorHandling: old.hasErrorHandling,
      hasLoadingState: old.hasLoadingState,
      hasEmptyState: old.hasEmptyState,
      isProductionReady: old.isProductionReady,
      missingItems: old.missingItems,
      nextAction: old.nextAction,
      lastCheckedAt: old.lastCheckedAt,
      diagnosisEnabled: enabled,
      diagnosisReplyStatus: old.diagnosisReplyStatus,
      diagnosisLastQuestion: old.diagnosisLastQuestion,
      diagnosisLastAnswer: old.diagnosisLastAnswer,
      diagnosisLastCheckedAt: old.diagnosisLastCheckedAt,
      diagnosisError: old.diagnosisError,
      buttonCount: old.buttonCount,
      formFieldCount: old.formFieldCount,
      linkCount: old.linkCount,
      tableActionCount: old.tableActionCount,
      filterCount: old.filterCount,
      navigationActionCount: old.navigationActionCount,
      totalInteractiveObjects: old.totalInteractiveObjects,
      screenPurpose: old.screenPurpose,
      primaryUserGoal: old.primaryUserGoal,
      expectedUserActions: old.expectedUserActions,
      businessReason: old.businessReason,
      screenPurposeStatus: old.screenPurposeStatus,
      needsReview: old.needsReview,
      productionReady: old.productionReady,
      falseProgress: old.falseProgress,
    );
  }
  final dbPath = r"C:\Users\Admin2\Documents\GitHub\primecare-platform\.agents\governance\governance.db";
  if (!File(dbPath).existsSync()) return;
  try {
    final db = sqlite3.open(dbPath);
    db.execute('UPDATE screens SET diagnosis_enabled = ? WHERE route_path = ?', [enabled ? 1 : 0, routePath]);
    db.dispose();
  } catch (e) {
    // Fail silently
  }
}

ScreenHealthStatus testSingleScreenReply(String routePath) {
  final dbPath = r"C:\Users\Admin2\Documents\GitHub\primecare-platform\.agents\governance\governance.db";
  
  String answer = '';
  String status = 'NOT_TESTED';
  String errorMsg = '';
  
  try {
    final health = getScreenHealth(routePath);
    if (health.componentFile == 'Unknown') {
      status = 'ERROR';
      errorMsg = 'Screen not registered in registry';
    } else {
      answer = askScreen(routePath, "Are you OK?");
      if (answer.contains("Status:")) {
        status = 'REPLIED_OK';
      } else if (answer.isEmpty) {
        status = 'NO_REPLY';
      } else {
        status = 'PARTIAL_REPLY';
      }
    }
  } catch (e) {
    status = 'ERROR';
    errorMsg = e.toString();
  }
  
  if (File(dbPath).existsSync()) {
    try {
      final db = sqlite3.open(dbPath);
      final screenRows = db.select('SELECT id FROM screens WHERE route_path = ?', [routePath]);
      int? screenId;
      if (screenRows.isNotEmpty) {
        screenId = screenRows.first['id'] as int;
      }
      
      final nowStr = DateTime.now().toIso8601String();
      
      db.execute('''
        UPDATE screens SET 
          diagnosis_reply_status = ?,
          diagnosis_last_question = ?,
          diagnosis_last_answer = ?,
          diagnosis_last_checked_at = ?,
          diagnosis_error = ?
        WHERE route_path = ?
      ''', [status, "Are you OK?", answer, nowStr, errorMsg, routePath]);
      
      if (screenId != null) {
        db.execute('''
          INSERT INTO screen_diagnosis_tests (screen_id, route_path, question, answer, reply_status, tested_at, error_message)
          VALUES (?, ?, ?, ?, ?, ?, ?)
        ''', [screenId, routePath, "Are you OK?", answer, status, nowStr, errorMsg]);
      }
      db.dispose();
    } catch (e) {
      // Fail silently
    }
  }
  
  final all = loadAllScreensFromDb();
  return all.firstWhere((s) => s.routePath == routePath, orElse: () => getScreenHealth(routePath));
}

List<ScreenHealthStatus> testAllScreenReplies() {
  final all = loadAllScreensFromDb();
  for (final s in all) {
    if (s.diagnosisEnabled) {
      testSingleScreenReply(s.routePath);
    }
  }
  return loadAllScreensFromDb();
}

